"""Component presets — the former file-based template library inlined as constants.

The YAML content is identical to the example templates kept in
``infrastructure/gitlab-components/examples/`` (historical reference only) but is
embedded here so runtime provisioning never reads files from disk.
"""

from __future__ import annotations

PRESETS: dict[str, dict] = {
    "docker_hub_to_harbor": {
        "name": "Docker Hub → Harbor copy (crane)",
        "description": "Copies Docker Hub image tags into a Harbor project using crane.",
        "content": '# GitLab CI/CD Component: Docker Hub → Harbor image copy (crane)\n#\n# Copies one or more tags of a Docker Hub image into a local Harbor project.\n# Uses go-containerregistry/crane, mirroring the exact mechanics of the BigBug\n# backend `DockerRegistryService.mirror_image()` (backend/app/services/docker.py):\n#   - references are scheme-less (`registry-1.docker.io/...`, `harbor.local:443/...`);\n#   - credentials live only in a 0600 `$DOCKER_CONFIG/config.json` (never argv);\n#   - `--insecure` is added when the target uses HTTP / a self-signed cert.\n#\n# Usage in a GitLab project `.gitlab-ci.yml`:\n#\n#     include:\n#       - component: $CI_SERVER_FQDN/bigbug-mirrors/components/docker-hub-to-harbor@1.0.0\n#         inputs:\n#           source_image: library/nginx\n#           target_registry: harbor.local:443\n#           target_repo: bigbug/nginx\n#           tags: 1.31.3 1.31.2 1.31.1 1.31 1.30.4\n#           target_user: robot$bigbug+bigbug-mirror\n#           target_password: "$HARBOR_ROBOT_SECRET"\n#           insecure: "true"\n\nspec:\n  inputs:\n    source_image:\n      description: "Full source repository path on Docker Hub (e.g. library/nginx)."\n      default: "library/nginx"\n    source_registry:\n      description: "Source registry host, scheme-less (default Docker Hub)."\n      default: "registry-1.docker.io"\n    source_user:\n      description: "Source registry username (empty = anonymous pull)."\n      default: ""\n    source_password:\n      description: "Source registry password/token (secret)."\n      default: ""\n    target_registry:\n      description: "Target Harbor host[:port], scheme-less (e.g. harbor.local:443)."\n    target_repo:\n      description: "Target repository path in Harbor (e.g. bigbug/nginx)."\n    target_user:\n      description: "Target Harbor username (e.g. robot account)."\n      default: ""\n    target_password:\n      description: "Target Harbor password/token (secret)."\n      default: ""\n    tags:\n      description: "Space/comma separated image tags to copy."\n      default: "latest"\n    insecure:\n      description: "Set to \'true\' when the target uses HTTP or a self-signed cert."\n      default: "false"\n\n---\n\n# ─────────────────────────────────────────────────────────────\n# Copy job (single job: sequential tag copies keep it simple)\n# ─────────────────────────────────────────────────────────────\ndocker-hub-to-harbor:\n  stage: sync\n  image:\n    name: gcr.io/go-containerregistry/crane:debug\n    # crane:debug\'s entrypoint is `/ko-app/crane`. If left intact, GitLab\n    # Runner runs the job script as `crane sh -c "<script>"` → "unknown\n    # command sh". Clearing the entrypoint lets the default shell (`/busybox/sh`,\n    # on PATH) execute the script while `crane` remains on PATH.\n    entrypoint: [""]\n  script:\n    - |\n      set -eu\n      [ -n "$target_registry" ] || { echo "ERROR: target_registry input is required"; exit 1; }\n      [ -n "$target_repo" ]    || { echo "ERROR: target_repo input is required"; exit 1; }\n\n      # Optional inputs default to empty so `set -u` never trips when the\n      # backend omits them from the pipeline variables (e.g. anonymous pull).\n      source_user="${source_user:-}"\n      source_password="${source_password:-}"\n      target_user="${target_user:-}"\n      target_password="${target_password:-}"\n      source_registry="${source_registry:-registry-1.docker.io}"\n      source_image="${source_image:-library/nginx}"\n      tags="${tags:-latest}"\n      insecure="${insecure:-false}"\n\n      # Normalize tag list (accept spaces or commas).\n      TAGS=$(printf \'%s\' "$tags" | tr \',\' \' \')\n\n      # Build a 0600 config.json so secrets never appear in argv (crane reads\n      # auth by registry host from $DOCKER_CONFIG/config.json).\n      DOCKER_CONFIG_DIR=$(mktemp -d)\n      trap \'rm -rf "$DOCKER_CONFIG_DIR"\' EXIT\n      export DOCKER_CONFIG="$DOCKER_CONFIG_DIR"\n\n      encode() { printf \'%s:%s\' "$1" "$2" | base64 | tr -d \'\\n\'; }\n\n      {\n        printf \'{"auths":{\'\n        FIRST=1\n        if [ -n "$target_user" ] && [ -n "$target_password" ]; then\n          printf \'"%s":{"auth":"%s"}\' "$target_registry" "$(encode "$target_user" "$target_password")"\n          FIRST=0\n        fi\n        if [ -n "$source_user" ] && [ -n "$source_password" ]; then\n          [ "$FIRST" -eq 1 ] || printf \',\'\n          printf \'"%s":{"auth":"%s"}\' "$source_registry" "$(encode "$source_user" "$source_password")"\n        fi\n        printf \'}}\'\n      } > "$DOCKER_CONFIG_DIR/config.json"\n      chmod 600 "$DOCKER_CONFIG_DIR/config.json"\n\n      INSECURE_FLAG=""\n      if [ "$insecure" = "true" ]; then\n        INSECURE_FLAG="--insecure"\n      fi\n\n      SYNCED=0\n      FAILED=0\n      for TAG in $TAGS; do\n        SRC="${source_registry}/${source_image}:${TAG}"\n        DST="${target_registry}/${target_repo}:${TAG}"\n        echo "==> crane copy ${SRC} -> ${DST}"\n        if crane copy $INSECURE_FLAG "$SRC" "$DST"; then\n          SYNCED=$((SYNCED + 1))\n        else\n          FAILED=$((FAILED + 1))\n        fi\n      done\n\n      echo "==> copy complete: ${SYNCED} succeeded, ${FAILED} failed"\n      [ "$FAILED" -eq 0 ] || exit 1\n  rules:\n    - if: \'$CI_PIPELINE_SOURCE == "api"\'\n    - if: \'$CI_PIPELINE_SOURCE == "trigger"\'\n    - if: \'$CI_PIPELINE_SOURCE == "web"\'\n    - if: \'$CI_PIPELINE_SOURCE == "schedule"\'\n',
    },
    "gold_image": {
        "name": "Gold (Base) Docker Image Build",
        "description": "Multi-arch gold image build with cosign signing and BigBug webhook notify.",
        "content": '# GitLab CI/CD Template: Gold (Base) Docker Image Build\n# Usage: include this template in your gold image project\'s .gitlab-ci.yml\n#\n# Required CI/CD variables:\n#   REGISTRY_URL         - Docker registry URL (e.g. registry.example.com)\n#   REGISTRY_USER        - Registry username\n#   REGISTRY_PASSWORD    - Registry password\n#   BIGBUG_API_URL       - BigBug backend URL\n#   BIGBUG_WEBHOOK_TOKEN - Shared secret for webhook authentication\n#\n# Optional CI/CD variables:\n#   COSIGN_PRIVATE_KEY   - Cosign private key for image signing\n#   COSIGN_PASSWORD      - Cosign private key password\n#   BUILD_PLATFORMS      - Comma-separated platforms (default: linux/amd64,linux/arm64)\n\nstages:\n  - build\n  - sign\n  - notify\n\nvariables:\n  DOCKER_DRIVER: overlay2\n  DOCKER_TLS_CERTDIR: "/certs"\n  BUILD_PLATFORMS: "linux/amd64,linux/arm64"\n  IMAGE_NAME: ""          # Override: e.g. ubuntu-22.04\n  IMAGE_TAG: ""           # Override: e.g. 1.0.0\n  DOCKERFILE_PATH: "Dockerfile"\n  BUILD_CONTEXT: "."\n  GOLD_IMAGE_ID: ""       # BigBug GoldImage ID (set by BigBug when triggering)\n\n# ─────────────────────────────────────────────\n# Build multi-arch gold image\n# ─────────────────────────────────────────────\nbuild-gold-image:\n  stage: build\n  image: docker:24-dind\n  services:\n    - docker:24-dind\n  before_script:\n    - docker info\n    - docker login -u "$REGISTRY_USER" -p "$REGISTRY_PASSWORD" "$REGISTRY_URL"\n    # Setup buildx for multi-arch\n    - docker buildx create --use --name multiarch-builder --driver docker-container || true\n    - docker buildx inspect --bootstrap\n  script:\n    - |\n      if [ -z "$IMAGE_NAME" ] || [ -z "$IMAGE_TAG" ]; then\n        echo "ERROR: IMAGE_NAME and IMAGE_TAG must be set"\n        exit 1\n      fi\n\n      FULL_IMAGE="${REGISTRY_URL}/${IMAGE_NAME}:${IMAGE_TAG}"\n      FULL_IMAGE_LATEST="${REGISTRY_URL}/${IMAGE_NAME}:latest"\n\n      echo "==> Building gold image: ${FULL_IMAGE}"\n      echo "==> Platforms: ${BUILD_PLATFORMS}"\n\n      docker buildx build \\\n        --platform "${BUILD_PLATFORMS}" \\\n        --file "${DOCKERFILE_PATH}" \\\n        --tag "${FULL_IMAGE}" \\\n        --tag "${FULL_IMAGE_LATEST}" \\\n        --label "org.opencontainers.image.created=$(date -u +%Y-%m-%dT%H:%M:%SZ)" \\\n        --label "org.opencontainers.image.revision=${CI_COMMIT_SHA}" \\\n        --label "org.opencontainers.image.source=${CI_PROJECT_URL}" \\\n        --label "bigbug.image.type=gold" \\\n        --label "bigbug.image.id=${GOLD_IMAGE_ID}" \\\n        --push \\\n        "${BUILD_CONTEXT}"\n\n      # Get image digest\n      DIGEST=$(docker buildx imagetools inspect "${FULL_IMAGE}" --format \'{{json .Manifest.Digest}}\' | tr -d \'"\')\n      echo "IMAGE_DIGEST=${DIGEST}" >> build.env\n      echo "FULL_IMAGE=${FULL_IMAGE}" >> build.env\n      echo "==> Build completed. Digest: ${DIGEST}"\n  artifacts:\n    reports:\n      dotenv: build.env\n    expire_in: 1 hour\n  rules:\n    - if: \'$CI_PIPELINE_SOURCE == "schedule"\'\n    - if: \'$CI_PIPELINE_SOURCE == "api"\'\n    - if: \'$CI_PIPELINE_SOURCE == "trigger"\'\n    - if: \'$CI_PIPELINE_SOURCE == "web"\'\n\n# ─────────────────────────────────────────────\n# Sign image with cosign\n# ─────────────────────────────────────────────\nsign-gold-image:\n  stage: sign\n  image: gcr.io/projectsigstore/cosign:v2.2.0\n  needs:\n    - job: build-gold-image\n      artifacts: true\n  before_script:\n    - |\n      if [ -z "$COSIGN_PRIVATE_KEY" ]; then\n        echo "COSIGN_PRIVATE_KEY not set, skipping signing"\n        exit 0\n      fi\n  script:\n    - |\n      if [ -z "$COSIGN_PRIVATE_KEY" ]; then\n        echo "Skipping image signing (no key configured)"\n        echo "COSIGN_SIGNATURE=" >> sign.env\n        exit 0\n      fi\n\n      echo "$COSIGN_PRIVATE_KEY" > /tmp/cosign.key\n      chmod 600 /tmp/cosign.key\n\n      echo "==> Signing image: ${FULL_IMAGE}"\n      COSIGN_PASSWORD="${COSIGN_PASSWORD}" cosign sign \\\n        --key /tmp/cosign.key \\\n        --yes \\\n        "${FULL_IMAGE}@${IMAGE_DIGEST}"\n\n      # Get signature\n      SIGNATURE=$(COSIGN_PASSWORD="${COSIGN_PASSWORD}" cosign triangulate "${FULL_IMAGE}@${IMAGE_DIGEST}" 2>/dev/null || echo "")\n      echo "COSIGN_SIGNATURE=${SIGNATURE}" >> sign.env\n      echo "==> Image signed successfully"\n\n      rm -f /tmp/cosign.key\n  artifacts:\n    reports:\n      dotenv: sign.env\n    expire_in: 1 hour\n  rules:\n    - if: \'$CI_PIPELINE_SOURCE == "schedule"\'\n    - if: \'$CI_PIPELINE_SOURCE == "api"\'\n    - if: \'$CI_PIPELINE_SOURCE == "trigger"\'\n    - if: \'$CI_PIPELINE_SOURCE == "web"\'\n\n# ─────────────────────────────────────────────\n# Notify BigBug backend\n# ─────────────────────────────────────────────\nnotify-bigbug:\n  stage: notify\n  image: alpine:latest\n  needs:\n    - job: build-gold-image\n      artifacts: true\n    - job: sign-gold-image\n      artifacts: true\n  before_script:\n    - apk add --no-cache curl\n  script:\n    - |\n      if [ -z "$BIGBUG_API_URL" ] || [ -z "$BIGBUG_WEBHOOK_TOKEN" ]; then\n        echo "BigBug webhook not configured, skipping notification"\n        exit 0\n      fi\n\n      IS_SIGNED="false"\n      if [ -n "$COSIGN_SIGNATURE" ]; then\n        IS_SIGNED="true"\n      fi\n\n      # Extract arch from platforms\n      ARCH_LIST=$(echo "$BUILD_PLATFORMS" | tr \',\' \'\\n\' | sed \'s|linux/||\' | tr \'\\n\' \',\' | sed \'s/,$//\')\n\n      curl -s -X POST "${BIGBUG_API_URL}/api/webhooks/gitlab" \\\n        -H "Content-Type: application/json" \\\n        -H "X-Webhook-Token: ${BIGBUG_WEBHOOK_TOKEN}" \\\n        -d "{\n          \\"object_kind\\": \\"pipeline\\",\n          \\"project\\": {\\"path_with_namespace\\": \\"${CI_PROJECT_PATH}\\"},\n          \\"object_attributes\\": {\n            \\"id\\": ${CI_PIPELINE_ID},\n            \\"status\\": \\"success\\",\n            \\"ref\\": \\"${CI_COMMIT_REF_NAME}\\",\n            \\"sha\\": \\"${CI_COMMIT_SHA}\\"\n          },\n          \\"pipeline_type\\": \\"gold_image_build\\",\n          \\"image_id\\": \\"${GOLD_IMAGE_ID}\\",\n          \\"image_tag\\": \\"${IMAGE_TAG}\\",\n          \\"sha256_digest\\": \\"${IMAGE_DIGEST}\\",\n          \\"cosign_signature\\": \\"${COSIGN_SIGNATURE}\\",\n          \\"is_signed\\": ${IS_SIGNED},\n          \\"arch\\": \\"${ARCH_LIST}\\",\n          \\"registry_url\\": \\"${REGISTRY_URL}\\",\n          \\"full_image\\": \\"${FULL_IMAGE}\\"\n        }" || echo "WARNING: Failed to notify BigBug"\n  rules:\n    - if: \'$CI_PIPELINE_SOURCE == "schedule"\'\n    - if: \'$CI_PIPELINE_SOURCE == "api"\'\n    - if: \'$CI_PIPELINE_SOURCE == "trigger"\'\n    - if: \'$CI_PIPELINE_SOURCE == "web"\'\n\nnotify-failure:\n  stage: notify\n  image: alpine:latest\n  before_script:\n    - apk add --no-cache curl\n  script:\n    - |\n      if [ -n "$BIGBUG_API_URL" ] && [ -n "$BIGBUG_WEBHOOK_TOKEN" ]; then\n        curl -s -X POST "${BIGBUG_API_URL}/api/webhooks/gitlab" \\\n          -H "Content-Type: application/json" \\\n          -H "X-Webhook-Token: ${BIGBUG_WEBHOOK_TOKEN}" \\\n          -d "{\n            \\"object_kind\\": \\"pipeline\\",\n            \\"project\\": {\\"path_with_namespace\\": \\"${CI_PROJECT_PATH}\\"},\n            \\"object_attributes\\": {\n              \\"id\\": ${CI_PIPELINE_ID},\n              \\"status\\": \\"failed\\",\n              \\"ref\\": \\"${CI_COMMIT_REF_NAME}\\",\n              \\"sha\\": \\"${CI_COMMIT_SHA}\\"\n            },\n            \\"pipeline_type\\": \\"gold_image_build\\",\n            \\"image_id\\": \\"${GOLD_IMAGE_ID}\\",\n            \\"message\\": \\"Gold image build pipeline failed\\"\n          }" || true\n      fi\n  rules:\n    - when: on_failure\n',
    },
    "app_image": {
        "name": "Application Docker Image Build",
        "description": "Application image build on a gold base with cosign signing and webhook notify.",
        "content": '# GitLab CI/CD Template: Application Docker Image Build\n# Usage: include this template in your app image project\'s .gitlab-ci.yml\n#\n# Required CI/CD variables:\n#   REGISTRY_URL         - Docker registry URL (e.g. registry.example.com)\n#   REGISTRY_USER        - Registry username\n#   REGISTRY_PASSWORD    - Registry password\n#   BIGBUG_API_URL       - BigBug backend URL\n#   BIGBUG_WEBHOOK_TOKEN - Shared secret for webhook authentication\n#\n# Optional CI/CD variables:\n#   COSIGN_PRIVATE_KEY   - Cosign private key for image signing\n#   COSIGN_PASSWORD      - Cosign private key password\n#   BUILD_PLATFORMS      - Comma-separated platforms (default: linux/amd64)\n#   GOLD_IMAGE_REF       - Base gold image reference (e.g. registry.example.com/ubuntu-22.04:latest)\n\nstages:\n  - prepare\n  - build\n  - sign\n  - notify\n\nvariables:\n  DOCKER_DRIVER: overlay2\n  DOCKER_TLS_CERTDIR: "/certs"\n  BUILD_PLATFORMS: "linux/amd64"\n  IMAGE_NAME: ""          # Override: e.g. myapp\n  IMAGE_TAG: ""           # Override: e.g. 1.2.3\n  DOCKERFILE_PATH: "Dockerfile"\n  BUILD_CONTEXT: "."\n  APP_IMAGE_ID: ""        # BigBug AppImage ID (set by BigBug when triggering)\n  GOLD_IMAGE_REF: ""      # Base gold image (e.g. registry.example.com/python:3.12-slim)\n  BUILD_ARGS: ""          # Additional --build-arg flags\n\n# ─────────────────────────────────────────────\n# Validate gold image availability\n# ─────────────────────────────────────────────\nvalidate-gold-image:\n  stage: prepare\n  image: docker:24-dind\n  services:\n    - docker:24-dind\n  script:\n    - |\n      if [ -z "$GOLD_IMAGE_REF" ]; then\n        echo "WARNING: GOLD_IMAGE_REF not set, using Dockerfile FROM directly"\n        exit 0\n      fi\n\n      docker login -u "$REGISTRY_USER" -p "$REGISTRY_PASSWORD" "$REGISTRY_URL"\n      echo "==> Validating gold image: ${GOLD_IMAGE_REF}"\n      docker pull "${GOLD_IMAGE_REF}"\n      echo "==> Gold image validated successfully"\n  rules:\n    - if: \'$CI_PIPELINE_SOURCE == "schedule"\'\n    - if: \'$CI_PIPELINE_SOURCE == "api"\'\n    - if: \'$CI_PIPELINE_SOURCE == "trigger"\'\n    - if: \'$CI_PIPELINE_SOURCE == "web"\'\n\n# ─────────────────────────────────────────────\n# Build application image\n# ─────────────────────────────────────────────\nbuild-app-image:\n  stage: build\n  image: docker:24-dind\n  services:\n    - docker:24-dind\n  needs:\n    - validate-gold-image\n  before_script:\n    - docker info\n    - docker login -u "$REGISTRY_USER" -p "$REGISTRY_PASSWORD" "$REGISTRY_URL"\n    - docker buildx create --use --name multiarch-builder --driver docker-container || true\n    - docker buildx inspect --bootstrap\n  script:\n    - |\n      if [ -z "$IMAGE_NAME" ] || [ -z "$IMAGE_TAG" ]; then\n        echo "ERROR: IMAGE_NAME and IMAGE_TAG must be set"\n        exit 1\n      fi\n\n      FULL_IMAGE="${REGISTRY_URL}/${IMAGE_NAME}:${IMAGE_TAG}"\n      FULL_IMAGE_LATEST="${REGISTRY_URL}/${IMAGE_NAME}:latest"\n\n      echo "==> Building app image: ${FULL_IMAGE}"\n      echo "==> Platforms: ${BUILD_PLATFORMS}"\n      echo "==> Base gold image: ${GOLD_IMAGE_REF:-\'from Dockerfile\'}"\n\n      # Build extra args\n      EXTRA_ARGS=""\n      if [ -n "$GOLD_IMAGE_REF" ]; then\n        EXTRA_ARGS="--build-arg BASE_IMAGE=${GOLD_IMAGE_REF}"\n      fi\n      if [ -n "$BUILD_ARGS" ]; then\n        EXTRA_ARGS="${EXTRA_ARGS} ${BUILD_ARGS}"\n      fi\n\n      docker buildx build \\\n        --platform "${BUILD_PLATFORMS}" \\\n        --file "${DOCKERFILE_PATH}" \\\n        --tag "${FULL_IMAGE}" \\\n        --tag "${FULL_IMAGE_LATEST}" \\\n        --label "org.opencontainers.image.created=$(date -u +%Y-%m-%dT%H:%M:%SZ)" \\\n        --label "org.opencontainers.image.revision=${CI_COMMIT_SHA}" \\\n        --label "org.opencontainers.image.source=${CI_PROJECT_URL}" \\\n        --label "bigbug.image.type=app" \\\n        --label "bigbug.image.id=${APP_IMAGE_ID}" \\\n        --label "bigbug.gold.image=${GOLD_IMAGE_REF}" \\\n        --cache-from "type=registry,ref=${FULL_IMAGE_LATEST}" \\\n        --cache-to "type=inline" \\\n        --push \\\n        ${EXTRA_ARGS} \\\n        "${BUILD_CONTEXT}"\n\n      # Get image digest\n      DIGEST=$(docker buildx imagetools inspect "${FULL_IMAGE}" --format \'{{json .Manifest.Digest}}\' | tr -d \'"\')\n      echo "IMAGE_DIGEST=${DIGEST}" >> build.env\n      echo "FULL_IMAGE=${FULL_IMAGE}" >> build.env\n      echo "==> Build completed. Digest: ${DIGEST}"\n  artifacts:\n    reports:\n      dotenv: build.env\n    expire_in: 1 hour\n  rules:\n    - if: \'$CI_PIPELINE_SOURCE == "schedule"\'\n    - if: \'$CI_PIPELINE_SOURCE == "api"\'\n    - if: \'$CI_PIPELINE_SOURCE == "trigger"\'\n    - if: \'$CI_PIPELINE_SOURCE == "web"\'\n\n# ─────────────────────────────────────────────\n# Sign image with cosign\n# ─────────────────────────────────────────────\nsign-app-image:\n  stage: sign\n  image: gcr.io/projectsigstore/cosign:v2.2.0\n  needs:\n    - job: build-app-image\n      artifacts: true\n  script:\n    - |\n      if [ -z "$COSIGN_PRIVATE_KEY" ]; then\n        echo "Skipping image signing (COSIGN_PRIVATE_KEY not configured)"\n        echo "COSIGN_SIGNATURE=" >> sign.env\n        exit 0\n      fi\n\n      echo "$COSIGN_PRIVATE_KEY" > /tmp/cosign.key\n      chmod 600 /tmp/cosign.key\n\n      echo "==> Signing image: ${FULL_IMAGE}"\n      COSIGN_PASSWORD="${COSIGN_PASSWORD}" cosign sign \\\n        --key /tmp/cosign.key \\\n        --yes \\\n        "${FULL_IMAGE}@${IMAGE_DIGEST}"\n\n      SIGNATURE=$(COSIGN_PASSWORD="${COSIGN_PASSWORD}" cosign triangulate "${FULL_IMAGE}@${IMAGE_DIGEST}" 2>/dev/null || echo "")\n      echo "COSIGN_SIGNATURE=${SIGNATURE}" >> sign.env\n      echo "==> Image signed successfully"\n\n      rm -f /tmp/cosign.key\n  artifacts:\n    reports:\n      dotenv: sign.env\n    expire_in: 1 hour\n  rules:\n    - if: \'$CI_PIPELINE_SOURCE == "schedule"\'\n    - if: \'$CI_PIPELINE_SOURCE == "api"\'\n    - if: \'$CI_PIPELINE_SOURCE == "trigger"\'\n    - if: \'$CI_PIPELINE_SOURCE == "web"\'\n\n# ─────────────────────────────────────────────\n# Notify BigBug backend\n# ─────────────────────────────────────────────\nnotify-bigbug:\n  stage: notify\n  image: alpine:latest\n  needs:\n    - job: build-app-image\n      artifacts: true\n    - job: sign-app-image\n      artifacts: true\n  before_script:\n    - apk add --no-cache curl\n  script:\n    - |\n      if [ -z "$BIGBUG_API_URL" ] || [ -z "$BIGBUG_WEBHOOK_TOKEN" ]; then\n        echo "BigBug webhook not configured, skipping notification"\n        exit 0\n      fi\n\n      IS_SIGNED="false"\n      if [ -n "$COSIGN_SIGNATURE" ]; then\n        IS_SIGNED="true"\n      fi\n\n      ARCH_LIST=$(echo "$BUILD_PLATFORMS" | tr \',\' \'\\n\' | sed \'s|linux/||\' | tr \'\\n\' \',\' | sed \'s/,$//\')\n\n      curl -s -X POST "${BIGBUG_API_URL}/api/webhooks/gitlab" \\\n        -H "Content-Type: application/json" \\\n        -H "X-Webhook-Token: ${BIGBUG_WEBHOOK_TOKEN}" \\\n        -d "{\n          \\"object_kind\\": \\"pipeline\\",\n          \\"project\\": {\\"path_with_namespace\\": \\"${CI_PROJECT_PATH}\\"},\n          \\"object_attributes\\": {\n            \\"id\\": ${CI_PIPELINE_ID},\n            \\"status\\": \\"success\\",\n            \\"ref\\": \\"${CI_COMMIT_REF_NAME}\\",\n            \\"sha\\": \\"${CI_COMMIT_SHA}\\"\n          },\n          \\"pipeline_type\\": \\"app_image_build\\",\n          \\"image_id\\": \\"${APP_IMAGE_ID}\\",\n          \\"image_tag\\": \\"${IMAGE_TAG}\\",\n          \\"sha256_digest\\": \\"${IMAGE_DIGEST}\\",\n          \\"cosign_signature\\": \\"${COSIGN_SIGNATURE}\\",\n          \\"is_signed\\": ${IS_SIGNED},\n          \\"arch\\": \\"${ARCH_LIST}\\",\n          \\"registry_url\\": \\"${REGISTRY_URL}\\",\n          \\"full_image\\": \\"${FULL_IMAGE}\\",\n          \\"gold_image_ref\\": \\"${GOLD_IMAGE_REF}\\"\n        }" || echo "WARNING: Failed to notify BigBug"\n  rules:\n    - if: \'$CI_PIPELINE_SOURCE == "schedule"\'\n    - if: \'$CI_PIPELINE_SOURCE == "api"\'\n    - if: \'$CI_PIPELINE_SOURCE == "trigger"\'\n    - if: \'$CI_PIPELINE_SOURCE == "web"\'\n\nnotify-failure:\n  stage: notify\n  image: alpine:latest\n  before_script:\n    - apk add --no-cache curl\n  script:\n    - |\n      if [ -n "$BIGBUG_API_URL" ] && [ -n "$BIGBUG_WEBHOOK_TOKEN" ]; then\n        curl -s -X POST "${BIGBUG_API_URL}/api/webhooks/gitlab" \\\n          -H "Content-Type: application/json" \\\n          -H "X-Webhook-Token: ${BIGBUG_WEBHOOK_TOKEN}" \\\n          -d "{\n            \\"object_kind\\": \\"pipeline\\",\n            \\"project\\": {\\"path_with_namespace\\": \\"${CI_PROJECT_PATH}\\"},\n            \\"object_attributes\\": {\n              \\"id\\": ${CI_PIPELINE_ID},\n              \\"status\\": \\"failed\\",\n              \\"ref\\": \\"${CI_COMMIT_REF_NAME}\\",\n              \\"sha\\": \\"${CI_COMMIT_SHA}\\"\n            },\n            \\"pipeline_type\\": \\"app_image_build\\",\n            \\"image_id\\": \\"${APP_IMAGE_ID}\\",\n            \\"message\\": \\"App image build pipeline failed\\"\n          }" || true\n      fi\n  rules:\n    - when: on_failure\n',
    },
    "mirror": {
        "name": "GitHub → GitLab Mirror Sync",
        "description": "Mirrors a GitHub repository into GitLab.",
        "content": '# GitLab CI/CD Template: GitHub → GitLab Mirror Sync\n# Usage: include this template in your project\'s .gitlab-ci.yml\n#\n# Required CI/CD variables (set in GitLab project/group settings):\n#   BIGBUG_API_URL       - BigBug backend URL (e.g. http://bigbug-backend:8000)\n#   BIGBUG_WEBHOOK_TOKEN - Shared secret for webhook authentication\n#   GITHUB_TOKEN         - GitHub personal access token (for private repos)\n\nstages:\n  - sync\n  - notify\n\nvariables:\n  GIT_STRATEGY: none\n  GIT_DEPTH: "0"\n\n# ─────────────────────────────────────────────\n# Mirror sync job\n# ─────────────────────────────────────────────\nmirror-sync:\n  stage: sync\n  image: alpine/git:latest\n  variables:\n    GITHUB_REPO_URL: ""      # Override per project: https://github.com/org/repo.git\n    GITLAB_REPO_URL: ""      # Override per project: https://gitlab.example.com/group/repo.git\n    SYNC_BRANCHES: "true"\n    SYNC_TAGS: "true"\n    SYNC_LFS: "false"\n  before_script:\n    - apk add --no-cache curl git\n    - git config --global credential.helper store\n    # Configure GitHub credentials\n    - |\n      if [ -n "$GITHUB_TOKEN" ]; then\n        echo "https://oauth2:${GITHUB_TOKEN}@github.com" >> ~/.git-credentials\n      fi\n    # Configure GitLab credentials\n    - |\n      if [ -n "$GITLAB_TOKEN" ]; then\n        GITLAB_HOST=$(echo "$GITLAB_REPO_URL" | sed \'s|https://||\' | cut -d\'/\' -f1)\n        echo "https://oauth2:${GITLAB_TOKEN}@${GITLAB_HOST}" >> ~/.git-credentials\n      fi\n  script:\n    - |\n      if [ -z "$GITHUB_REPO_URL" ] || [ -z "$GITLAB_REPO_URL" ]; then\n        echo "ERROR: GITHUB_REPO_URL and GITLAB_REPO_URL must be set"\n        exit 1\n      fi\n\n      echo "==> Cloning from GitHub: $GITHUB_REPO_URL"\n      git clone --mirror "$GITHUB_REPO_URL" repo.git\n      cd repo.git\n\n      echo "==> Pushing to GitLab: $GITLAB_REPO_URL"\n      git remote add gitlab "$GITLAB_REPO_URL"\n\n      PUSH_ARGS="--mirror"\n      if [ "$SYNC_TAGS" = "false" ]; then\n        PUSH_ARGS="--all"\n      fi\n\n      git push gitlab $PUSH_ARGS --force\n\n      echo "==> Sync completed successfully"\n      SYNC_STATUS="success"\n      SYNC_MESSAGE="Mirror sync completed"\n  after_script:\n    - |\n      # Notify BigBug backend about sync result\n      if [ -n "$BIGBUG_API_URL" ] && [ -n "$BIGBUG_WEBHOOK_TOKEN" ]; then\n        STATUS="${SYNC_STATUS:-failed}"\n        MESSAGE="${SYNC_MESSAGE:-Sync failed}"\n        curl -s -X POST "${BIGBUG_API_URL}/api/webhooks/gitlab" \\\n          -H "Content-Type: application/json" \\\n          -H "X-Webhook-Token: ${BIGBUG_WEBHOOK_TOKEN}" \\\n          -d "{\n            \\"object_kind\\": \\"pipeline\\",\n            \\"project\\": {\\"path_with_namespace\\": \\"${CI_PROJECT_PATH}\\"},\n            \\"object_attributes\\": {\n              \\"id\\": ${CI_PIPELINE_ID},\n              \\"status\\": \\"${STATUS}\\",\n              \\"ref\\": \\"${CI_COMMIT_REF_NAME}\\",\n              \\"sha\\": \\"${CI_COMMIT_SHA}\\"\n            },\n            \\"pipeline_type\\": \\"mirror_sync\\",\n            \\"message\\": \\"${MESSAGE}\\"\n          }" || echo "WARNING: Failed to notify BigBug backend"\n      fi\n  rules:\n    - if: \'$CI_PIPELINE_SOURCE == "schedule"\'\n    - if: \'$CI_PIPELINE_SOURCE == "api"\'\n    - if: \'$CI_PIPELINE_SOURCE == "trigger"\'\n    - if: \'$CI_PIPELINE_SOURCE == "web"\'\n\n# ─────────────────────────────────────────────\n# Notify on failure\n# ─────────────────────────────────────────────\nnotify-failure:\n  stage: notify\n  image: alpine:latest\n  before_script:\n    - apk add --no-cache curl\n  script:\n    - |\n      echo "Mirror sync FAILED for pipeline ${CI_PIPELINE_ID}"\n      if [ -n "$BIGBUG_API_URL" ] && [ -n "$BIGBUG_WEBHOOK_TOKEN" ]; then\n        curl -s -X POST "${BIGBUG_API_URL}/api/webhooks/gitlab" \\\n          -H "Content-Type: application/json" \\\n          -H "X-Webhook-Token: ${BIGBUG_WEBHOOK_TOKEN}" \\\n          -d "{\n            \\"object_kind\\": \\"pipeline\\",\n            \\"project\\": {\\"path_with_namespace\\": \\"${CI_PROJECT_PATH}\\"},\n            \\"object_attributes\\": {\n              \\"id\\": ${CI_PIPELINE_ID},\n              \\"status\\": \\"failed\\",\n              \\"ref\\": \\"${CI_COMMIT_REF_NAME}\\",\n              \\"sha\\": \\"${CI_COMMIT_SHA}\\"\n            },\n            \\"pipeline_type\\": \\"mirror_sync\\",\n            \\"message\\": \\"Mirror sync pipeline failed\\"\n          }" || true\n      fi\n  rules:\n    - when: on_failure\n',
    },
    "docker_sync": {
        "name": "Docker Image Sync",
        "description": "Fetches Docker image tags from a registry and notifies BigBug.",
        "content": '# GitLab CI Template: Docker Image Sync\n#\n# This pipeline fetches Docker image tags from an external registry and\n# notifies the BigBug backend about the sync result.\n#\n# Required CI/CD variables (set in GitLab project or at trigger time):\n#   DOCKER_REGISTRY_URL   – Docker Registry API v2 base URL (e.g., https://registry-1.docker.io/v2)\n#   DOCKER_IMAGE_NAME     – Image name to sync (e.g., library/nginx)\n#   DOCKER_REGISTRY_USER  – (optional) Registry username for authentication\n#   DOCKER_REGISTRY_PASS  – (optional) Registry password/token\n#   BIGBUG_WEBHOOK_URL    – BigBug webhook endpoint (e.g., https://bigbug.example.com/api/webhooks/gitlab)\n#   BIGBUG_WEBHOOK_TOKEN  – (optional) Bearer token for webhook auth\n#   SYNC_STRATEGY         – "all" (sync every tag) or "latest" (only top-N)\n#   TAG_FILTER            – (optional) Regex to filter tags (e.g., "^1\\\\.\\\\d+")\n#   TAG_LIMIT             – (optional) Max tags to sync when strategy=latest (default: 10)\n\nstages:\n  - sync\n  - notify\n\nvariables:\n  SYNC_STRATEGY: "all"\n  TAG_LIMIT: "10"\n\n.docker_login: &docker_login\n  - |\n    if [ -n "$DOCKER_REGISTRY_USER" ] && [ -n "$DOCKER_REGISTRY_PASS" ]; then\n      echo "$DOCKER_REGISTRY_PASS" | docker login "$DOCKER_REGISTRY_URL" \\\n        --username "$DOCKER_REGISTRY_USER" --password-stdin\n    fi\n\n.bigbug_notify: &bigbug_notify\n  - |\n    AUTH_HEADER=""\n    if [ -n "$BIGBUG_WEBHOOK_TOKEN" ]; then\n      AUTH_HEADER="-H \'Authorization: Bearer $BIGBUG_WEBHOOK_TOKEN\'"\n    fi\n\n    if [ "$CI_JOB_STATUS" = "success" ]; then\n      STATUS="success"\n    else\n      STATUS="failed"\n    fi\n\n    curl -sS -X POST "$BIGBUG_WEBHOOK_URL" \\\n      -H "Content-Type: application/json" \\\n      $AUTH_HEADER \\\n      -d "{\n        \\"object_kind\\": \\"pipeline\\",\n        \\"object_attributes\\": {\n          \\"id\\": $CI_PIPELINE_ID,\n          \\"status\\": \\"$STATUS\\"\n        },\n        \\"project\\": {\n          \\"web_url\\": \\"$CI_PROJECT_URL\\"\n        }\n      }" || true\n\n# ──── Sync Job ────────────────────────────────────────────────────────────\n\ndocker-sync:\n  stage: sync\n  image: docker:27-dind\n  services:\n    - docker:27-dind\n  variables:\n    DOCKER_TLS_CERTDIR: ""\n  before_script:\n    - *docker_login\n  script:\n    - |\n      echo "==> Syncing Docker image: ${DOCKER_IMAGE_NAME}"\n      echo "    Registry: ${DOCKER_REGISTRY_URL}"\n\n      # Resolve the registry host (strip /v2 suffix if present)\n      REGISTRY_HOST=$(echo "$DOCKER_REGISTRY_URL" | sed \'s|/v2/*$||\')\n\n      # Build tag list args\n      TAG_ARGS=""\n      if [ "$SYNC_STRATEGY" = "latest" ]; then\n        TAG_ARGS="--limit ${TAG_LIMIT}"\n      fi\n\n      if [ -n "$TAG_FILTER" ]; then\n        TAG_ARGS="$TAG_ARGS --filter \'${TAG_FILTER}\'"\n      fi\n\n      # List tags via registry API\n      # Use docker manifest inspect to validate each tag\n      TAGS_URL="${REGISTRY_HOST}/v2/${DOCKER_IMAGE_NAME}/tags/list"\n      echo "    Fetching tags from: ${TAGS_URL}"\n\n      TAGS_RESPONSE=$(curl -sS -f "$TAGS_URL" 2>&1) || {\n        echo "ERROR: Failed to fetch tags list: $TAGS_RESPONSE"\n        exit 1\n      }\n\n      TAG_COUNT=$(echo "$TAGS_RESPONSE" | python3 -c "\nimport json, sys\ndata = json.load(sys.stdin)\ntags = data.get(\'tags\', [])\nprint(len(tags))\nfor t in tags:\n    print(t)\n" 2>&1)\n\n      TOTAL=$(echo "$TAG_COUNT" | head -1)\n      echo "    Found ${TOTAL} tag(s)"\n\n      # Pull each tag to cache it in the local registry\n      TAGS=$(echo "$TAG_COUNT" | tail -n +2)\n\n      SYNCED=0\n      FAILED=0\n      for TAG in $TAGS; do\n        FULL_IMAGE="${REGISTRY_HOST}/${DOCKER_IMAGE_NAME}:${TAG}"\n        echo "    Pulling: ${FULL_IMAGE}"\n        if docker pull "$FULL_IMAGE" 2>&1; then\n          SYNCED=$((SYNCED + 1))\n          echo "      ✓ Pulled successfully"\n        else\n          FAILED=$((FAILED + 1))\n          echo "      ✗ Pull failed"\n        fi\n      done\n\n      echo "==> Sync complete: ${SYNCED} succeeded, ${FAILED} failed"\n      if [ $FAILED -gt 0 ]; then\n        exit 1\n      fi\n  after_script:\n    - *bigbug_notify\n  rules:\n    - if: \'$DOCKER_REGISTRY_URL == null || $DOCKER_REGISTRY_URL == ""\'\n      when: never\n    - if: \'$DOCKER_IMAGE_NAME == null || $DOCKER_IMAGE_NAME == ""\'\n      when: never\n    - when: always\n  tags:\n    - docker\n\n# ──── Failure Notification ────────────────────────────────────────────────\n\nnotify-failure:\n  stage: notify\n  image: alpine:3.21\n  script:\n    - *bigbug_notify\n  when: on_failure\n  needs:\n    - docker-sync\n',
    },
    "helm_sync": {
        "name": "Helm Chart Repository Sync",
        "description": "Syncs Helm chart repository into GitLab and notifies BigBug.",
        "content": '# GitLab CI/CD Template: Helm Chart Repository Sync\n# Usage: include this template in your helm-mirror project\'s .gitlab-ci.yml\n#\n# Required CI/CD variables (set in GitLab project/group settings):\n#   BIGBUG_API_URL       - BigBug backend URL (e.g. http://bigbug-backend:8000)\n#   BIGBUG_WEBHOOK_TOKEN - Shared secret for webhook authentication\n#   HELM_REPO_URL        - URL to the Helm chart repository index.yaml\n#   HELM_REPO_NAME       - Name of the Helm chart source in BigBug\n#\n# Optional CI/CD variables:\n#   GITLAB_REPO_URL      - GitLab repo to mirror charts to (default: this project)\n#   SYNC_STRATEGY        - "full" (clone entire repo) or "incremental" (default)\n#   CHART_FILTER         - Comma-separated list of chart names to sync (default: all)\n\nstages:\n  - sync\n  - notify\n\nvariables:\n  GIT_STRATEGY: none\n  HELM_REPO_URL: ""       # Override per project\n  HELM_REPO_NAME: ""      # Override per project\n  SYNC_STRATEGY: "incremental"\n  CHART_FILTER: ""\n\n# ─────────────────────────────────────────────\n# Helm chart sync job\n# ─────────────────────────────────────────────\nhelm-sync:\n  stage: sync\n  image: alpine/helm:latest\n  before_script:\n    - apk add --no-cache curl git yq\n    - helm plugin install https://github.com/chartmuseum/helm-push || true\n  script:\n    - |\n      if [ -z "$HELM_REPO_URL" ] || [ -z "$HELM_REPO_NAME" ]; then\n        echo "ERROR: HELM_REPO_URL and HELM_REPO_NAME must be set"\n        exit 1\n      fi\n\n      echo "==> Adding Helm repo: ${HELM_REPO_NAME}"\n      helm repo add "${HELM_REPO_NAME}" "${HELM_REPO_URL}"\n      helm repo update "${HELM_REPO_NAME}"\n\n      echo "==> Fetching available charts"\n      CHARTS=$(helm search repo "${HELM_REPO_NAME}" -o json)\n\n      if [ -n "$CHART_FILTER" ]; then\n        echo "==> Filtering charts: ${CHART_FILTER}"\n      fi\n\n      # Prepare local chart storage\n      mkdir -p charts\n      cd charts\n\n      # Download all chart versions\n      echo "$CHARTS" | jq -r \'.[] | "\\(.name) \\(.version)"\' | while read -r chart_name chart_version; do\n        # Strip repo prefix from chart name\n        short_name=$(echo "$chart_name" | sed "s|${HELM_REPO_NAME}/||")\n\n        # Apply chart filter if set\n        if [ -n "$CHART_FILTER" ]; then\n          MATCH=0\n          echo "$CHART_FILTER" | tr \',\' \'\\n\' | while read -r filter; do\n            if echo "$short_name" | grep -q "$filter"; then\n              MATCH=1\n            fi\n          done\n          if [ "$MATCH" = "0" ]; then\n            continue\n          fi\n        fi\n\n        echo "==> Pulling chart: ${chart_name} v${chart_version}"\n        helm pull "${chart_name}" --version "${chart_version}" --untar || echo "WARNING: Failed to pull ${chart_name} v${chart_version}" && continue\n\n        echo "==> Chart ${chart_name} v${chart_version} downloaded"\n      done\n\n      echo "==> Sync completed"\n      SYNC_STATUS="success"\n      SYNC_MESSAGE="Helm chart sync completed successfully. Repository: ${HELM_REPO_NAME}"\n  after_script:\n    - |\n      # Notify BigBug backend about sync result\n      if [ -n "$BIGBUG_API_URL" ] && [ -n "$BIGBUG_WEBHOOK_TOKEN" ]; then\n        STATUS="${SYNC_STATUS:-failed}"\n        MESSAGE="${SYNC_MESSAGE:-Helm chart sync failed}"\n        curl -s -X POST "${BIGBUG_API_URL}/api/webhooks/gitlab" \\\n          -H "Content-Type: application/json" \\\n          -H "X-Webhook-Token: ${BIGBUG_WEBHOOK_TOKEN}" \\\n          -d "{\n            \\"object_kind\\": \\"pipeline\\",\n            \\"project\\": {\\"path_with_namespace\\": \\"${CI_PROJECT_PATH}\\"},\n            \\"object_attributes\\": {\n              \\"id\\": ${CI_PIPELINE_ID},\n              \\"status\\": \\"${STATUS}\\",\n              \\"ref\\": \\"${CI_COMMIT_REF_NAME}\\",\n              \\"sha\\": \\"${CI_COMMIT_SHA}\\"\n            },\n            \\"pipeline_type\\": \\"helm_sync\\",\n            \\"helm_repo_name\\": \\"${HELM_REPO_NAME}\\",\n            \\"helm_repo_url\\": \\"${HELM_REPO_URL}\\",\n            \\"message\\": \\"${MESSAGE}\\"\n          }" || echo "WARNING: Failed to notify BigBug backend"\n      fi\n  rules:\n    - if: \'$CI_PIPELINE_SOURCE == "schedule"\'\n    - if: \'$CI_PIPELINE_SOURCE == "api"\'\n    - if: \'$CI_PIPELINE_SOURCE == "trigger"\'\n    - if: \'$CI_PIPELINE_SOURCE == "web"\'\n\n# ─────────────────────────────────────────────\n# Notify on failure\n# ─────────────────────────────────────────────\nnotify-failure:\n  stage: notify\n  image: alpine:latest\n  before_script:\n    - apk add --no-cache curl\n  script:\n    - |\n      echo "Helm chart sync FAILED for pipeline ${CI_PIPELINE_ID}"\n      if [ -n "$BIGBUG_API_URL" ] && [ -n "$BIGBUG_WEBHOOK_TOKEN" ]; then\n        curl -s -X POST "${BIGBUG_API_URL}/api/webhooks/gitlab" \\\n          -H "Content-Type: application/json" \\\n          -H "X-Webhook-Token: ${BIGBUG_WEBHOOK_TOKEN}" \\\n          -d "{\n            \\"object_kind\\": \\"pipeline\\",\n            \\"project\\": {\\"path_with_namespace\\": \\"${CI_PROJECT_PATH}\\"},\n            \\"object_attributes\\": {\n              \\"id\\": ${CI_PIPELINE_ID},\n              \\"status\\": \\"failed\\",\n              \\"ref\\": \\"${CI_COMMIT_REF_NAME}\\",\n              \\"sha\\": \\"${CI_COMMIT_SHA}\\"\n            },\n            \\"pipeline_type\\": \\"helm_sync\\",\n            \\"helm_repo_name\\": \\"${HELM_REPO_NAME}\\",\n            \\"message\\": \\"Helm chart sync pipeline failed\\"\n          }" || true\n      fi\n  rules:\n    - when: on_failure\n',
    },
}


def extract_inputs_schema(content: str) -> dict:
    """Extract a JSON Schema from a GitLab component ``spec.inputs`` block.

    GitLab CI/CD components declare inputs in a flat ``spec:`` header (input
    name → ``type``/``default``/``description``). This returns a JSON-Schema
    subset suitable for auto-generating the BigBug component form. The
    template presets (gold/app/mirror/docker/helm) carry no ``spec`` and thus
    yield an empty schema.

    ponytail: hand-rolled indentation parser for our flat ``spec: inputs:``
    shape — replace with PyYAML if presets ever grow nested input structures.
    """
    lines = content.splitlines()
    in_inputs = False
    current_input: str | None = None
    meta: dict[str, dict[str, str]] = {}

    for raw in lines:
        if raw == "spec:":
            in_inputs = False
            continue
        if raw == "  inputs:":
            in_inputs = True
            continue
        if not in_inputs:
            continue
        if raw.startswith("    ") and not raw.startswith("      "):
            name = raw.strip().rstrip(":")
            if name:
                current_input = name
                meta[name] = {}
            continue
        if raw.startswith("      ") and current_input is not None:
            body = raw.strip()
            key, _, value = body.partition(":")
            key = key.strip()
            value = value.strip().strip("\"'")
            if key in ("description", "default", "type"):
                meta[current_input][key] = value
            continue

    if not meta:
        return {}

    schema: dict = {"type": "object", "properties": {}}
    required: list[str] = []
    for name, fields in meta.items():
        prop: dict = {"type": fields.get("type", "string")}
        if "description" in fields:
            prop["description"] = fields["description"]
        if "default" in fields:
            prop["default"] = fields["default"]
        else:
            required.append(name)
        schema["properties"][name] = prop
    if required:
        schema["required"] = required
    return schema
